import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — Two-Factor Authentication (2FA, TOTP)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/plan.md","filePath":"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/plan.md"}'),c={name:"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/plan.md"};function i(s,e,l,r,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="plan-—-two-factor-authentication-2fa-totp" tabindex="-1">Plan — Two-Factor Authentication (2FA, TOTP) <a class="header-anchor" href="#plan-—-two-factor-authentication-2fa-totp" aria-label="Permalink to &quot;Plan — Two-Factor Authentication (2FA, TOTP)&quot;">​</a></h1><p>&gt; Link: <a href="./spec.html">spec.md</a> — Cho user bật 2FA bằng TOTP (scan QR), KHÔNG copy secret, KHÔNG backup codes.</p><h2 id="pham-vi-ky-thuat" tabindex="-1">Phạm vi kỹ thuật <a class="header-anchor" href="#pham-vi-ky-thuat" aria-label="Permalink to &quot;Phạm vi kỹ thuật&quot;">​</a></h2><ul><li><strong>brandhub-business-service</strong> (backend). FE render QR từ <code>otpAuthUrl</code> — ngoài phạm vi plan này.</li><li>File sửa/tạo: <ul><li><code>util/TotpUtil.java</code> (MỚI) — RFC 6238 HMAC-SHA1 + Base32, stdlib.</li><li><code>model/User.java</code> — thêm <code>twoFactorEnabled</code> (boolean), <code>totpSecret</code> (String).</li><li><code>exception/ErrorCode.java</code> — thêm <code>TWO_FA_*</code>.</li><li><code>service/AuthService.java</code> + <code>service/impl/AuthServiceImpl.java</code> — 3 method setup/confirm/disable + verify.</li><li><code>controller/AuthController.java</code> — endpoint <code>/2fa/*</code>.</li><li><code>util/JwtUtil.java</code> — <code>generateTwoFactorToken</code> (JWT ngắn hạn 5 phút, claim <code>type=2fa</code>).</li></ul></li></ul><h2 id="api-contract-final" tabindex="-1">API Contract (final) <a class="header-anchor" href="#api-contract-final" aria-label="Permalink to &quot;API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/auth/2fa/setup     (Authorization: Bearer)</span></span>
<span class="line"><span>  → 200 { success:true, data:{ otpAuthUrl:&quot;otpauth://totp/BrandHub:...@...&quot; } }</span></span>
<span class="line"><span>  Không trả secretKey plaintext.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/auth/2fa/confirm   { code:&quot;123456&quot; } (Authorization)</span></span>
<span class="line"><span>  → 200 { success:true, data:null }   (bật twoFactorEnabled=true)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/auth/2fa/disable   { code:&quot;123456&quot; } (Authorization)</span></span>
<span class="line"><span>  → 200 { success:true, data:null }   (tắt, xóa totpSecret)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/auth/2fa/verify    { twoFactorToken:&quot;...&quot;, code:&quot;123456&quot; }  (KHÔNG cần auth)</span></span>
<span class="line"><span>  → 200 { data:{ accessToken, tokenType, expiresIn, requireTwoFactor:false } }</span></span>
<span class="line"><span>  (điểm hoàn tất login khi 2FA bật; set refresh cookie như login thường)</span></span></code></pre></div><p><code>/2fa/verify</code> bắt buộc để hoàn tất luồng login-2FA (đã có trong spec.md mục 5). Confirm/disable require Authorization (cần đăng nhập), verify thì không.</p><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><ul><li><code>users</code> thêm 2 cột: <code>two_factor_enabled</code> (bool, default false), <code>totp_secret</code> (varchar 64, nullable).</li><li>Secret PENDING lưu Redis <code>2fa:setup:{userId}</code> (TTL 10 phút) — chỉ ghi vào <code>users</code> khi confirm thành công, tránh trạng thái nửa-vời.</li><li>Migration: cần ALTER TABLE thêm 2 cột (Flyway/Liquibase nếu có; hiện chưa thấy migration framework — dev chạy tay).</li></ul><h2 id="luong-xu-ly" tabindex="-1">Luồng xử lý <a class="header-anchor" href="#luong-xu-ly" aria-label="Permalink to &quot;Luồng xử lý&quot;">​</a></h2><ol><li><strong>setup</strong>: check chưa bật → sinh secret 160-bit → lưu Redis <code>2fa:setup:{userId}</code> → trả <code>otpauth://</code> URI (không trả secret).</li><li><strong>confirm</strong>: lấy secret pending từ Redis → <code>TotpUtil.verify</code> (±1 step) → đúng thì ghi <code>totpSecret</code> + <code>twoFactorEnabled=true</code>, xóa Redis. Sai → <code>TWO_FA_CODE_INVALID</code>.</li><li><strong>disable</strong>: check đang bật → verify code với <code>totpSecret</code> → đúng thì tắt + null secret.</li><li><strong>verify</strong> (login-2FA): parse <code>twoFactorToken</code>, check claim <code>type=2fa</code>, load user, verify code, issue token (tái dùng <code>completeLogin</code>).</li></ol><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li>Không phụ thuộc feature khác. FR 3.2.2 (login) đọc <code>twoFactorEnabled</code> để phân nhánh — phải xong trước/song song.</li></ul><h2 id="rui-ro-ky-thuat" tabindex="-1">Rủi ro kỹ thuật <a class="header-anchor" href="#rui-ro-ky-thuat" aria-label="Permalink to &quot;Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Clock drift</strong> giữa server/app Authenticator → cho phép ±1 step (WINDOW=1).</li><li><strong>Mất app Authenticator</strong> không có backup code (đã bỏ) → phải nhờ Admin (FR 3.10.5), chấp nhận trade-off đã chốt.</li><li><strong>Bỏ copy secret</strong> → FE không cần secret, giảm surface. QR render từ <code>otpAuthUrl</code> (có thể dùng lib QR phía FE).</li><li><strong>Đổi tên field 2026-09-23:</strong> <code>TwoFactorSetupResponse</code> đổi <code>qrCodeUrl</code> → <code>otpAuthUrl</code> để phản ánh đúng nội dung (đây là <code>otpauth://</code> URI, không phải URL ảnh QR). FE đọc <code>data.otpAuthUrl</code>.</li><li><strong>BR-86 lockout (2026-09-25):</strong> thêm <code>checkTwoFactorAttempt</code> trong <code>AuthServiceImpl</code> — Redis key <code>2fa:attempt:{userId}</code> TTL 10 phút, max 5 lần sai (<code>OTP_MAX_ATTEMPTS</code>, tái dùng constant có sẵn) → 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code>. Áp dụng chung cho confirm/disable/verify.</li></ul>`,15)])])}const g=t(c,[["render",i]]);export{u as __pageData,g as default};
